let currentLang = 'ru';

function t(key) {
  const dict = I18N[currentLang] || I18N.ru;
  return (key in dict) ? dict[key] : (I18N.ru[key] || key);
}

function setLang(lang) {
  currentLang = I18N[lang] ? lang : 'ru';
}

function getLang() {
  return currentLang;
}
